<template><div class="page"><div class="page-head"><div><h1 class="page-title">图书管理</h1><div class="page-sub">维护书目信息、馆藏数量及上架状态</div></div><el-button type="primary" :icon="Plus" @click="open()">新增图书</el-button></div><div class="toolbar"><el-input v-model="keyword" clearable placeholder="搜索书名、ISBN或作者" style="width:320px" @keyup.enter="load"><template #prefix><el-icon><Search/></el-icon></template></el-input><el-button type="primary" plain @click="load">查询</el-button><el-button @click="keyword='';load()">重置</el-button></div><el-card class="table-card"><el-table :data="rows" v-loading="loading"><el-table-column label="图书" min-width="250"><template #default="{row}"><div class="book-cell"><div class="fake-cover">{{row.title.slice(0,1)}}</div><div><b>{{row.title}}</b><small>{{row.authorName}}</small></div></div></template></el-table-column><el-table-column prop="isbn" label="ISBN" width="145"/><el-table-column prop="categoryName" label="分类" width="110"><template #default="{row}"><el-tag effect="light" type="success">{{row.categoryName}}</el-tag></template></el-table-column><el-table-column prop="publisherName" label="出版社" min-width="150"/><el-table-column label="馆藏/可借" width="110"><template #default="{row}"><b>{{row.totalCopies}}</b> / <span style="color:#26956f">{{row.availableCopies}}</span></template></el-table-column><el-table-column prop="location" label="馆藏位置" width="120"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{row.status===1?'上架':'下架'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-popconfirm title="确定删除这本图书吗？" @confirm="remove(row.id)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column></el-table><div class="pagination"><el-pagination background layout="total, prev, pager, next" :total="total" v-model:current-page="page" @current-change="load"/></div></el-card><el-dialog v-model="visible" :title="form.id?'编辑图书':'新增图书'" width="680px"><el-form label-position="top" :model="form"><div class="form-grid"><el-form-item label="图书名称"><el-input v-model="form.title"/></el-form-item><el-form-item label="ISBN"><el-input v-model="form.isbn"/></el-form-item><el-form-item label="作者"><el-input v-model="form.authorName"/></el-form-item><el-form-item label="分类"><el-select v-model="form.categoryId" style="width:100%"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="出版社"><el-select v-model="form.publisherId" style="width:100%"><el-option v-for="p in publishers" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><el-form-item label="出版日期"><el-date-picker v-model="form.publishDate" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item><el-form-item label="馆藏数量"><el-input-number v-model="form.totalCopies" :min="0" style="width:100%"/></el-form-item><el-form-item label="馆藏位置"><el-input v-model="form.location"/></el-form-item></div><el-form-item label="内容简介"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{ref,reactive,onMounted}from'vue';import{Plus}from'@element-plus/icons-vue';import{ElMessage}from'element-plus';import api from'../api';const rows=ref<any[]>([]),categories=ref<any[]>([]),publishers=ref<any[]>([]),total=ref(0),page=ref(1),keyword=ref(''),loading=ref(false),visible=ref(false),form=reactive<any>({});onMounted(async()=>{[categories.value,publishers.value]=await Promise.all([api.get('/api/categories'),api.get('/api/publishers')]);load()});async function load(){loading.value=true;try{const r:any=await api.get('/api/books',{params:{page:page.value,size:10,keyword:keyword.value}});rows.value=r.records;total.value=r.total}finally{loading.value=false}}function open(r:any={}){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,r,{totalCopies:r.totalCopies??1,availableCopies:r.availableCopies??1,status:r.status??1});visible.value=true}async function save(){if(!form.title||!form.isbn)return ElMessage.warning('请填写图书名称和ISBN');form.id?await api.put(`/api/books/${form.id}`,form):await api.post('/api/books',form);ElMessage.success('保存成功');visible.value=false;load()}async function remove(id:number){await api.delete(`/api/books/${id}`);ElMessage.success('删除成功');load()}</script><style scoped>.book-cell{display:flex;align-items:center;gap:12px}.book-cell small{display:block;color:#98a4b3;margin-top:5px}.fake-cover{width:38px;height:50px;border-radius:6px;background:linear-gradient(145deg,#1c9271,#46b68f);display:grid;place-items:center;color:#fff;font-size:18px;font-weight:700;box-shadow:0 5px 12px rgba(36,147,111,.2)}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}</style>
